INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63429260', 63429260, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'konsultan Asisten Pendukung kegiatan Prioritas industri Halal', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 93600000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', '. Pelaksanaan dukungan teknis-operasional dalam kegiatan prioritas industri halal, termasuk membantu kelancaran aktivitas lapangan dan kegiatan pendukung lainnya, di bawah arahan ASN penanggung jawab. 2. Pengumpulan dan pengelolaan informasi non-kebijakan yang berasal dari pelaksanaan kegiatan industri halal sebagai bahan pendukung untuk memahami perkembangan dan capaian kegiatan, di bawah arahan ASN penanggung jawab. 3. Fasilitasi dan pendampingan teknis kegiatan, termasuk membantu komunikasi teknis dan dukungan koordinatif dengan para pihak terkait tanpa kewenangan pengambilan keputusan, serta di bawah pengawasan ASN penanggung jawab. 4. Pengelolaan dokumentasi dan administrasi kegiatan, yang meliputi penyiapan bahan teknis, pencatatan pelaksanaan kegiatan, serta pengarsipan dokumen pendukung secara tertib dan sistematis, di bawah arahan ASN penanggung jawab. 5. Penyusunan bahan informasi pendukung berbasis kegiatan, sesuai arahan ASN penanggung jawab, untuk memberikan gambaran mengenai keterkaitan peningkatan daya saing industri yang memproduksi produk halal dengan perkembangan sektor industri pengolahan.', 'Dokumen analisis kondisi terkini industri halal nasional Termin 1 tanggal 2 Februari 2026 Feb Dokumen analisis perkembangan dan potensi industri halal pada subsektor industri prioritas Termin 2 tanggal 2 Maret 2026 Mar Dokumen analisis tantangan serta hambatan teknis dan non-teknis pengembangan industri halal Termin 3 tanggal 1 April 2026 Apr Dokumen pemetaan rantai nilai (halal value chain) industri halal Termin 4 tanggal 4 Mei 2026 Mei Dokumen analisis kebijakan pendukung dan penguatan ekosistem industri halal Termin 5 tanggal 1 Juni 2026 Juni Dokumen analisis praktik baik (best practices) pengembangan industri halal Termin 6 tanggal 1 Juli 2026 Juli Dokumen evaluasi sementara pelaksanaan kebijakan dan program industri halal Termin 7 tanggal 3 Agustus 2026 Agt Dokumen analisis strategi penguatan daya saing industri halal nasional sektor industri halal subsektor makanan dan minuman halal serta kosmetik dan farmasi halal Termin 8 tanggal 1 September 2026 Sept Dokumen analisis strategi penguatan daya saing industri halal nasional sektor industri halal subsektor teksil, kulit, dan fesyen muslim Termin 9 tanggal 1 Oktober 2026 Okt Dokumen rekomendasi kebijakan pengembangan industri halal nasional Termin 10 tanggal 2 November 2026 Nov Des Dokumen dampak kegiatan fasilitasi dan pembinaan industri halal terhadap peningkatan kapasitas, akses pasar, dan kinerja UMKM/IKM Dokumen dampak kegiatan industri halal nasional dan internasional terhadap pelaku usaha, peningkatan pendapatan, perluasan pasar, serta kontribusinya terhadap kinerja industri pengolahan', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 944447);
